"use client";

import React, { useState, useMemo } from "react";
import { 
  CalendarDays, MapPin, Filter, ChevronDown, 
  Globe, Sparkles, Flag, ArrowRight 
} from "lucide-react";

/* --- 1. DATASET --- */
const HOLIDAYS_DB = [
  // 2025
  { id: 1, name: "New Year's Day", date: "Jan 01", monthIdx: 0, day: "Wed", year: "2025", type: "Public", country: "Global", region: "All" },
  { id: 2, name: "Republic Day", date: "Jan 26", monthIdx: 0, day: "Sun", year: "2025", type: "National", country: "India", region: "All" },
  { id: 3, name: "Presidents' Day", date: "Feb 17", monthIdx: 1, day: "Mon", year: "2025", type: "Public", country: "USA", region: "All" },
  { id: 4, name: "Holi", date: "Mar 14", monthIdx: 2, day: "Fri", year: "2025", type: "Optional", country: "India", region: "North India" },
  { id: 5, name: "Good Friday", date: "Apr 18", monthIdx: 3, day: "Fri", year: "2025", type: "Public", country: "Global", region: "All" },
  
  // 2026
  { id: 6, name: "New Year's Day", date: "Jan 01", monthIdx: 0, day: "Thu", year: "2026", type: "Public", country: "Global", region: "All" },
  { id: 7, name: "Republic Day", date: "Jan 26", monthIdx: 0, day: "Mon", year: "2026", type: "National", country: "India", region: "All" },
  { id: 8, name: "Ugadi", date: "Mar 19", monthIdx: 2, day: "Thu", year: "2026", type: "Optional", country: "India", region: "Telangana" },
  { id: 9, name: "Memorial Day", date: "May 25", monthIdx: 4, day: "Mon", year: "2026", type: "Public", country: "USA", region: "All" },
  { id: 10, name: "Kannada Rajyotsava", date: "Nov 01", monthIdx: 10, day: "Sun", year: "2026", type: "Optional", country: "India", region: "Karnataka" },
  { id: 11, name: "Christmas", date: "Dec 25", monthIdx: 11, day: "Fri", year: "2026", type: "Public", country: "Global", region: "All" },
];

const MONTH_NAMES = ["January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"];
const REGIONS_BY_COUNTRY: any = {
    "All": ["All", "Telangana", "Karnataka", "North India", "New York"],
    "India": ["All", "Telangana", "Karnataka", "North India"],
    "USA": ["All", "New York", "California"],
    "Global": ["All"]
};

export default function PremiumHolidayTimeline() {
  const [year, setYear] = useState("2026");
  const [country, setCountry] = useState("All");
  const [region, setRegion] = useState("All");
  const [type, setType] = useState("All");

  /* --- LOGIC ENGINE --- */
  const groupedHolidays = useMemo(() => {
    const filtered = HOLIDAYS_DB.filter((h) => {
      const matchYear = h.year === year;
      const matchCountry = country === "All" || h.country === country || h.country === "Global";
      const matchRegion = region === "All" || h.region === region || h.region === "All";
      const matchType = type === "All" || h.type === type;
      return matchYear && matchCountry && matchRegion && matchType;
    });

    filtered.sort((a, b) => a.monthIdx - b.monthIdx);

    const groups: Record<string, typeof filtered> = {};
    filtered.forEach(h => {
        const monthKey = MONTH_NAMES[h.monthIdx];
        if (!groups[monthKey]) groups[monthKey] = [];
        groups[monthKey].push(h);
    });

    return groups;
  }, [year, country, region, type]);

  return (
    <div className="min-h-screen bg-[#FAFAFA] dark:bg-[#050505] text-slate-900 dark:text-slate-100 font-sans pb-24">
      
      {/* --- 1. EDITORIAL HEADER --- */}
      <div className="pt-20 pb-16 px-6 lg:px-12 max-w-7xl mx-auto">
         <div className="flex flex-col gap-6">
            <div className="flex items-center gap-3">
               <span className="px-3 py-1 rounded-full bg-slate-900 dark:bg-white text-white dark:text-black text-[10px] font-black uppercase tracking-widest">
                  Fiscal Year {year}
               </span>
               <div className="h-[1px] w-12 bg-slate-200 dark:bg-slate-800" />
               <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">
                  Official Schedule
               </span>
            </div>
            
            <h1 className="text-6xl lg:text-8xl font-black tracking-tighter uppercase text-slate-900 dark:text-white leading-[0.9]">
               Holiday <br /> <span className="text-slate-300 dark:text-slate-800">Timeline.</span>
            </h1>
         </div>
      </div>

      {/* --- 2. STICKY GLASS FILTER BAR --- */}
      <div className="sticky top-6 z-40 px-6 lg:px-12 mb-16">
         <div className="max-w-7xl mx-auto">
            <div className="bg-white/80 dark:bg-[#111111]/80 backdrop-blur-xl border border-slate-200 dark:border-slate-800 p-2 rounded-2xl shadow-xl shadow-slate-200/40 dark:shadow-black/50 flex flex-col md:flex-row gap-2 justify-between">
               
               <div className="flex flex-wrap gap-2 flex-1">
                  <GlassSelect label="Year" value={year} onChange={setYear} options={['2025', '2026']} icon={<CalendarDays size={14}/>} />
                  <GlassSelect label="Country" value={country} onChange={(v: string)=>{setCountry(v); setRegion('All')}} options={['All', 'India', 'USA']} icon={<Flag size={14}/>} />
                  <GlassSelect label="Region" value={region} onChange={setRegion} options={REGIONS_BY_COUNTRY[country] || ['All']} disabled={country === 'Global'} icon={<MapPin size={14}/>} />
               </div>

               <div className="bg-slate-100 dark:bg-white/5 rounded-xl p-1 flex items-center">
                  {['All', 'Public', 'Optional'].map(t => (
                     <button key={t} onClick={() => setType(t)} className={`px-4 py-2.5 rounded-lg text-[9px] font-black uppercase tracking-widest transition-all ${type === t ? "bg-white dark:bg-brand-600 shadow-sm text-slate-900 dark:text-white" : "text-slate-400 hover:text-slate-600 dark:hover:text-slate-300"}`}>
                        {t}
                     </button>
                  ))}
               </div>
            </div>
         </div>
      </div>

      {/* --- 3. TIMELINE SECTIONS --- */}
      <div className="px-6 lg:px-12 max-w-7xl mx-auto space-y-20">
         {Object.keys(groupedHolidays).length > 0 ? (
            Object.keys(groupedHolidays).map((month) => (
               <div key={month} className="flex flex-col lg:flex-row gap-8 lg:gap-20 group/month">
                  
                  {/* Left: Editorial Month Label */}
                  <div className="lg:w-48 flex-shrink-0 pt-2 sticky top-32 self-start">
                     <h2 className="text-4xl font-black text-slate-200 dark:text-slate-800 uppercase tracking-tighter group-hover/month:text-slate-900 dark:group-hover/month:text-white transition-colors duration-500">
                        {month.substring(0,3)}
                     </h2>
                     <span className="text-xs font-bold text-slate-400 uppercase tracking-widest mt-2 block pl-1 border-l-2 border-slate-200 dark:border-slate-800 group-hover/month:border-brand-500 transition-colors">
                        {month}
                     </span>
                  </div>

                  {/* Right: The Grid */}
                  <div className="flex-1 grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6">
                     {groupedHolidays[month].map((h) => (
                        <PremiumCard key={h.id} data={h} />
                     ))}
                  </div>
               </div>
            ))
         ) : (
            <div className="py-32 text-center">
               <div className="inline-flex items-center justify-center w-16 h-16 rounded-full bg-slate-100 dark:bg-slate-900 mb-6">
                  <Filter className="w-6 h-6 text-slate-400" />
               </div>
               <p className="text-sm font-black text-slate-300 dark:text-slate-700 uppercase tracking-widest">No holidays found</p>
            </div>
         )}
      </div>

    </div>
  );
}

/* --- PREMIUM CARD COMPONENT --- */
const PremiumCard = ({ data }: { data: any }) => (
   <div className="group relative bg-white dark:bg-[#0A0A0A] rounded-[1.5rem] p-6 border border-slate-100 dark:border-white/10 hover:border-brand-500/30 dark:hover:border-brand-500/50 transition-all duration-300 hover:shadow-2xl hover:shadow-brand-500/5 hover:-translate-y-1">
      
      {/* Top Meta Row */}
      <div className="flex justify-between items-start mb-8">
         <div className="flex flex-col">
            <span className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1">{data.day}</span>
            <span className="text-3xl font-black text-slate-900 dark:text-white leading-none tracking-tight">{data.date.split(' ')[1]}</span>
         </div>
         <div className={`px-2.5 py-1 rounded-full border ${data.type === 'Optional' ? 'bg-amber-50 border-amber-100 text-amber-600 dark:bg-amber-500/10 dark:border-amber-500/20 dark:text-amber-500' : 'bg-slate-50 border-slate-100 text-slate-600 dark:bg-white/5 dark:border-white/5 dark:text-slate-300'}`}>
            <span className="text-[9px] font-black uppercase tracking-widest flex items-center gap-1.5">
               {data.type === 'Optional' ? <Sparkles size={10} /> : <Globe size={10} />}
               {data.type}
            </span>
         </div>
      </div>

      {/* Bottom Content */}
      <div className="relative">
         <h3 className="text-lg font-bold text-slate-900 dark:text-white leading-tight mb-2 group-hover:text-brand-600 transition-colors">
            {data.name}
         </h3>
         <div className="flex items-center gap-2 text-slate-400">
            <MapPin size={12} />
            <span className="text-[10px] font-bold uppercase tracking-widest">
               {data.country === 'Global' ? 'Global Operations' : data.region}
            </span>
         </div>
         
         {/* Subtle Arrow Interaction */}
         <div className="absolute right-0 bottom-0 opacity-0 -translate-x-2 group-hover:opacity-100 group-hover:translate-x-0 transition-all duration-300">
            <ArrowRight size={16} className="text-brand-500" />
         </div>
      </div>
   </div>
);

/* --- GLASS SELECT COMPONENT --- */
const GlassSelect = ({ label, value, onChange, options, disabled, icon }: any) => (
   <div className={`relative h-10 flex-1 min-w-[140px] group ${disabled ? 'opacity-40 pointer-events-none' : ''}`}>
      <div className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400 group-hover:text-brand-500 transition-colors">{icon}</div>
      <select 
         value={value} 
         onChange={(e) => onChange(e.target.value)} 
         disabled={disabled}
         className="w-full h-full bg-slate-50 dark:bg-white/5 rounded-xl pl-9 pr-8 text-[10px] font-bold uppercase tracking-widest text-slate-700 dark:text-slate-200 outline-none cursor-pointer appearance-none border border-transparent hover:border-slate-200 dark:hover:border-white/10 transition-all"
      >
         {options.map((opt: string) => <option key={opt} value={opt}>{opt}</option>)}
      </select>
      <ChevronDown size={12} className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-300 pointer-events-none" />
   </div>
);